using HRM.Models;using HRM.Models.WorkPlanning;using HRM.WorkPlanning.Abstractions;using Microsoft.EntityFrameworkCore;
namespace HRM.WorkPlanning.Services;
public sealed class WorkforcePolicyManagementService(IDbContextFactory<HrmTeContext> factory):IWorkforcePolicyManagementService{public async Task<IReadOnlyList<WorkforceDutyTypeRow>>GetDutyTypesAsync(int org,CancellationToken ct=default){await using var db=await factory.CreateDbContextAsync(ct);return await db.DutyTypes.AsNoTracking().Where(x=>x.OrganisationId==org).OrderBy(x=>x.Name).Select(x=>new WorkforceDutyTypeRow(x.Id,x.Code,x.Name,x.Category,x.AttendanceStrategy,x.WorkTemplateId,x.IsActive)).ToListAsync(ct);}public async Task<IReadOnlyList<WorkforcePolicyRow>>GetPoliciesAsync(int org,CancellationToken ct=default){await using var db=await factory.CreateDbContextAsync(ct);return await db.WorkforcePolicies.AsNoTracking().Where(x=>x.OrganisationId==org).OrderByDescending(x=>x.EffectiveFrom).Select(x=>new WorkforcePolicyRow(x.Id,x.Code,x.Name,x.RulesJson,DateOnly.FromDateTime(x.EffectiveFrom),x.EffectiveTo==null?null:DateOnly.FromDateTime(x.EffectiveTo.Value),x.Version,x.IsActive)).ToListAsync(ct);}public async Task<IReadOnlyList<WorkforcePolicyAssignmentRow>>GetAssignmentsAsync(int org,CancellationToken ct=default){await using var db=await factory.CreateDbContextAsync(ct);return await db.WorkforcePolicyAssignments.AsNoTracking().Where(x=>x.OrganisationId==org).OrderByDescending(x=>x.Priority).ThenByDescending(x=>x.EffectiveFrom).Select(x=>new WorkforcePolicyAssignmentRow(x.Id,x.WorkforcePolicyId,x.WorkforcePolicy.Name,x.JobId,x.IndividualId,x.DutyTypeId,DateOnly.FromDateTime(x.EffectiveFrom),x.EffectiveTo==null?null:DateOnly.FromDateTime(x.EffectiveTo.Value),x.Priority,x.IsActive)).ToListAsync(ct);}public async Task<int>CreateDutyTypeAsync(DutyTypeInput i,CancellationToken ct=default){if(string.IsNullOrWhiteSpace(i.Code)||string.IsNullOrWhiteSpace(i.Name))throw new InvalidOperationException("Duty type code and name are required.");await using var db=await factory.CreateDbContextAsync(ct);var row=new DutyType{OrganisationId=i.OrganisationId,Code=i.Code.Trim().ToUpperInvariant(),Name=i.Name.Trim(),Category=i.Category.Trim(),AttendanceStrategy=i.AttendanceStrategy.Trim(),WorkTemplateId=i.WorkTemplateId,OperationLogId=i.OperationLogId};db.DutyTypes.Add(row);await db.SaveChangesAsync(ct);return row.Id;}public async Task<int>CreatePolicyAsync(WorkforcePolicyInput i,CancellationToken ct=default){if(string.IsNullOrWhiteSpace(i.Code)||string.IsNullOrWhiteSpace(i.Name)||i.EffectiveTo<i.EffectiveFrom)throw new InvalidOperationException("Policy code, name and effective dates are invalid.");System.Text.Json.JsonDocument.Parse(i.RulesJson);await using var db=await factory.CreateDbContextAsync(ct);var row=new WorkforcePolicy{OrganisationId=i.OrganisationId,Code=i.Code.Trim().ToUpperInvariant(),Name=i.Name.Trim(),RulesJson=i.RulesJson,EffectiveFrom=i.EffectiveFrom.ToDateTime(TimeOnly.MinValue),EffectiveTo=i.EffectiveTo?.ToDateTime(TimeOnly.MinValue),OperationLogId=i.OperationLogId};db.WorkforcePolicies.Add(row);await db.SaveChangesAsync(ct);return row.Id;}public async Task<int>CreateAssignmentAsync(WorkforcePolicyAssignmentInput i,CancellationToken ct=default){if(i.EffectiveTo<i.EffectiveFrom||i.Priority<0)throw new InvalidOperationException("Policy assignment dates or priority are invalid.");await using var db=await factory.CreateDbContextAsync(ct);if(!await db.WorkforcePolicies.AnyAsync(x=>x.Id==i.WorkforcePolicyId&&x.OrganisationId==i.OrganisationId,ct))throw new InvalidOperationException("Select a policy in the current organisation.");if(i.JobId.HasValue&&!await db.Jobs.AnyAsync(x=>x.JobId==i.JobId&&x.OrganisationID==i.OrganisationId,ct))throw new InvalidOperationException("Selected job is outside the current organisation.");if(i.DutyTypeId.HasValue&&!await db.DutyTypes.AnyAsync(x=>x.Id==i.DutyTypeId&&x.OrganisationId==i.OrganisationId,ct))throw new InvalidOperationException("Selected duty type is outside the current organisation.");if(i.IndividualId.HasValue&&i.JobId.HasValue&&!await db.Jobs.AnyAsync(x=>x.JobId==i.JobId&&x.IndividualID==i.IndividualId&&x.OrganisationID==i.OrganisationId,ct))throw new InvalidOperationException("Selected staff member does not hold the selected job.");var row=new WorkforcePolicyAssignment{OrganisationId=i.OrganisationId,WorkforcePolicyId=i.WorkforcePolicyId,JobId=i.JobId,IndividualId=i.IndividualId,DutyTypeId=i.DutyTypeId,EffectiveFrom=i.EffectiveFrom.ToDateTime(TimeOnly.MinValue),EffectiveTo=i.EffectiveTo?.ToDateTime(TimeOnly.MinValue),Priority=i.Priority,OperationLogId=i.OperationLogId};db.WorkforcePolicyAssignments.Add(row);await db.SaveChangesAsync(ct);return row.Id;}}
